SELECT COALESCE((SELECT group_concat(jp || '^^' || zh, '@@') FROM (SELECT jp, zh FROM (SELECT CAST(key AS INTEGER) AS k, CASE WHEN type = 'object' THEN CASE WHEN json_type(value, '$.jp') = 'text' THEN trim(json_extract(value, '$.jp'), ' ' || char(9) || char(10) || char(13)) END END AS jp, CASE WHEN type = 'object' THEN CASE WHEN json_type(value, '$.zh') = 'text' THEN trim(json_extract(value, '$.zh'), ' ' || char(9) || char(10) || char(13)) END END AS zh FROM json_each(:examples)) WHERE jp IS NOT NULL AND zh IS NOT NULL AND jp <> '' AND zh <> '' AND instr(jp, '^^') = 0 AND instr(jp, '@@') = 0 AND instr(zh, '^^') = 0 AND instr(zh, '@@') = 0 ORDER BY k)), '')
